//! Cheap generated and minified file detection, in the spirit of `scc -z`.
//!
//! Generated code pollutes business line counts, so it is classified once per
//! file: a comment marker near the top or bottom of the file, or an average
//! line length no human writes by hand.

use crate::lexer::Analysis;

/// Average line length that marks a file as machine-minified.
pub const DEFAULT_MIN_LINE_LENGTH: usize = 255;

/// Comment markers that give a file away as machine written.
const MARKERS: [&str; 9] = [
    "@generated",
    "do not edit",
    "code generated",
    "generated by",
    "generated file",
    "automatically generated",
    "auto-generated",
    "autogenerated",
    "this file is generated",
];

/// Lines searched at the top and at the bottom for a marker.
const HEAD_LINES: usize = 15;
const TAIL_LINES: usize = 3;

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub enum Generated {
    #[default]
    None,
    Generated,
    Minified,
}

impl Generated {
    pub fn is_some(self) -> bool {
        !matches!(self, Generated::None)
    }

    /// Bare tag used in JSON and CSV: "", "gen" or "min".
    pub fn label(self) -> &'static str {
        match self {
            Generated::None => "",
            Generated::Generated => "gen",
            Generated::Minified => "min",
        }
    }

    /// Suffix appended to a file label in listings.
    pub fn tag(self) -> &'static str {
        match self {
            Generated::None => "",
            Generated::Generated => " (gen)",
            Generated::Minified => " (min)",
        }
    }
}

/// Classify one file from its text and the line classes the lexer produced.
pub fn detect(text: &str, analysis: &Analysis, min_line_length: usize) -> Generated {
    if has_marker(text, analysis) {
        return Generated::Generated;
    }
    if min_line_length > 0 && analysis.total > 0 && text.len() / analysis.total >= min_line_length {
        return Generated::Minified;
    }
    Generated::None
}

/// Look for a generator marker in a comment near the top or bottom.
fn has_marker(text: &str, analysis: &Analysis) -> bool {
    let total = analysis.total;
    for (index, raw) in text.lines().enumerate() {
        if index >= total {
            break;
        }
        if index >= HEAD_LINES && index + TAIL_LINES < total {
            continue;
        }
        if !analysis.comment.get(index).copied().unwrap_or(false) {
            continue;
        }
        let lower = raw.to_ascii_lowercase();
        if MARKERS.iter().any(|marker| lower.contains(marker)) {
            return true;
        }
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lexer;

    fn classify(text: &str) -> Generated {
        let analysis = lexer::analyze(text);
        detect(text, &analysis, DEFAULT_MIN_LINE_LENGTH)
    }

    #[test]
    fn head_markers_are_recognised() {
        for text in [
            "// @generated by protoc\nfn a() {}\n",
            "// Code generated by tonic. DO NOT EDIT.\nfn a() {}\n",
            "/* This file is automatically generated */\nfn a() {}\n",
            "//! Autogenerated module.\nfn a() {}\n",
        ] {
            assert_eq!(classify(text), Generated::Generated, "{}", text);
        }
    }

    #[test]
    fn trailing_markers_are_recognised() {
        let text = "fn a() {}\nfn b() {}\n// do not edit\n";
        assert_eq!(classify(text), Generated::Generated);
    }

    #[test]
    fn hand_written_comments_stay_business() {
        assert_eq!(
            classify("//! Hand written module.\nfn a() {}\n"),
            Generated::None
        );
        assert_eq!(classify("fn a() {}\n"), Generated::None);
        assert_eq!(classify(""), Generated::None);
    }

    #[test]
    fn markers_buried_in_the_middle_are_ignored() {
        let mut text = String::new();
        for index in 0..40 {
            text.push_str(&format!("// filler {}\n", index));
        }
        text.push_str("// @generated\n");
        for _ in 0..40 {
            text.push_str("fn a() {}\n");
        }
        assert_eq!(classify(&text), Generated::None);
    }

    #[test]
    fn markers_inside_strings_are_not_comments() {
        let text = "fn a() {\n    let s = \"// @generated\";\n}\n";
        assert_eq!(classify(text), Generated::None);
    }

    #[test]
    fn long_average_lines_mark_a_file_minified() {
        let text = format!("const A: &str = \"{}\";\n", "x".repeat(600));
        assert_eq!(classify(&text), Generated::Minified);
        let analysis = lexer::analyze(&text);
        assert_eq!(detect(&text, &analysis, 0), Generated::None);
    }

    #[test]
    fn tags_and_labels_match_the_classification() {
        assert_eq!(Generated::None.tag(), "");
        assert_eq!(Generated::Generated.tag(), " (gen)");
        assert_eq!(Generated::Minified.tag(), " (min)");
        assert_eq!(Generated::None.label(), "");
        assert_eq!(Generated::Generated.label(), "gen");
        assert_eq!(Generated::Minified.label(), "min");
        assert!(!Generated::None.is_some());
        assert!(Generated::Generated.is_some());
    }
}
